import React, { useRef, useState } from 'react';
import { motion, useScroll, useTransform, useMotionValue, useSpring } from 'framer-motion';
import './Contact.css';

// Custom hook for Magnetic Button Physics
const MagneticOrb = ({ children, color, href }) => {
  const ref = useRef(null);
  const [position, setPosition] = useState({ x: 0, y: 0 });

  const mouseMove = (e) => {
    const { clientX, clientY } = e;
    const { width, height, left, top } = ref.current.getBoundingClientRect();
    const x = clientX - (left + width / 2);
    const y = clientY - (top + height / 2);
    setPosition({ x, y });
  };

  const mouseLeave = () => {
    setPosition({ x: 0, y: 0 });
  };

  return (
    <motion.a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      ref={ref}
      onMouseMove={mouseMove}
      onMouseLeave={mouseLeave}
      animate={{ x: position.x * 0.3, y: position.y * 0.3 }}
      transition={{ type: "spring", stiffness: 150, damping: 15, mass: 0.1 }}
      className={`magnetic-orb ${color}`}
    >
      <motion.div
        className="orb-content"
        animate={{ x: position.x * 0.1, y: position.y * 0.1 }}
      >
        {children}
      </motion.div>
    </motion.a>
  );
};

const Contact = () => {
  const containerRef = useRef(null);

  // Massive background marquee scroll effect
  const { scrollYProgress } = useScroll({ target: containerRef, offset: ["start end", "end start"] });
  const marqueeX1 = useTransform(scrollYProgress, [0, 1], ["0%", "-50%"]);
  const marqueeX2 = useTransform(scrollYProgress, [0, 1], ["-50%", "0%"]);

  return (
    <section id="contact" className="insane-contact-section" ref={containerRef}>

      {/* Massive Background Marquee Text */}
      <div className="contact-marquee-wrapper">
        <motion.div className="contact-marquee-row outline-text" style={{ x: marqueeX1 }}>
          LET'S CONNECT — LET'S CONNECT — LET'S CONNECT — LET'S CONNECT — LET'S CONNECT —
        </motion.div>
        <motion.div className="contact-marquee-row filled-text" style={{ x: marqueeX2 }}>
          WORK TOGETHER — WORK TOGETHER — WORK TOGETHER — WORK TOGETHER — WORK TOGETHER —
        </motion.div>
      </div>

      <div className="container relative z-10">

        <div className="insane-contact-grid">

          {/* Left Side: Huge Typography & Identity */}
          <div className="contact-left-col">
            <motion.div
              initial={{ opacity: 0, y: 100 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.8, type: "spring" }}
            >
              <div className="glitch-status">
                <div className="status-dot"></div>
                <span>ACCEPTING NEW PROJECTS</span>
              </div>
              <h2 className="insane-title">
                Have an<br />
                <span className="gradient-highlight">Idea?</span>
              </h2>
              <motion.p
              className="insane-subtitle"
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: 0.4 }}
            >
              Don't let it stay just an idea. Drop a message, and let's engineer something phenomenal together.
            </motion.p>
          </motion.div>
        </div>

        {/* Right Side: Magnetic Floating Orbs replacing traditional cards */}
          <div className="contact-right-col">

            {/* Email Orb */}
            <motion.a
              href="mailto:pritishjadhav2006@gmail.com"
              className="magnetic-orb orb-email"
              initial={{ opacity: 0, scale: 0.8 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6 }}
              whileTap={{ scale: 0.95 }}
            >
              <div className="orb-content">
                <i className="fas fa-paper-plane orb-icon"></i>
                <div>
                  <div className="orb-label">Email Me</div>
                  <div className="orb-detail">pritishjadhav2006@gmail.com</div>
                </div>
              </div>
            </motion.a>

            {/* WhatsApp Orb */}
            <motion.a 
              href="https://wa.me/918605720415"
              target="_blank"
              rel="noopener noreferrer"
              className="magnetic-orb orb-wa"
              initial={{ opacity: 0, scale: 0.8 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: 0.2 }}
              whileTap={{ scale: 0.95 }}
            >
              <div className="orb-content">
                <i className="fab fa-whatsapp orb-icon"></i>
                <div>
                  <div className="orb-label">WhatsApp Chat</div>
                  <div className="orb-detail">+91 86057 20415</div>
                </div>
              </div>
            </motion.a>

            {/* Social Matrix (mini orbs) */}
            <motion.div
              className="social-matrix"
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.8, delay: 0.6 }}
            >
              <a href="https://www.linkedin.com/in/pritish-jadhav-205141339?utm_source=share&utm_campaign=share_via&utm_content=profile&utm_medium=android_app" target="_blank" rel="noopener noreferrer" className="mini-magnetic" title="LinkedIn">
                <svg viewBox="0 0 24 24" fill="currentColor"><path d="M19 0h-14c-2.761 0-5 2.239-5 5v14c0 2.761 2.239 5 5 5h14c2.762 0 5-2.239 5-5v-14c0-2.761-2.238-5-5-5zm-11 19h-3v-11h3v11zm-1.5-12.268c-.966 0-1.75-.79-1.75-1.764s.784-1.764 1.75-1.764 1.75.79 1.75 1.764-.783 1.764-1.75 1.764zm13.5 12.268h-3v-5.604c0-3.368-4-3.113-4 0v5.604h-3v-11h3v1.765c1.396-2.586 7-2.777 7 2.476v6.759z"/></svg>
              </a>
              <a href="https://github.com/pritishjadhav" target="_blank" rel="noopener noreferrer" className="mini-magnetic" title="GitHub">
                <svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z"/></svg>
              </a>
              <a href="https://x.com/Pritish2006" target="_blank" rel="noopener noreferrer" className="mini-magnetic" title="Twitter">
                <svg viewBox="0 0 24 24" fill="currentColor"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
              </a>
              <a href="https://www.instagram.com/jadhav_pritish_26?igsh=aDNmY2ZzdGk4aTVz" target="_blank" rel="noopener noreferrer" className="mini-magnetic" title="Instagram">
                <svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.266.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.013-3.583.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zm0-2.163c-3.259 0-3.667.014-4.947.072-4.358.2-6.78 2.618-6.98 6.98-.059 1.281-.073 1.689-.073 4.948 0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98 1.281.058 1.689.072 4.948.072 3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98-1.281-.059-1.69-.073-4.949-.073zm0 5.838c-3.403 0-6.162 2.759-6.162 6.162s2.759 6.163 6.162 6.163 6.162-2.759 6.162-6.163c0-3.403-2.759-6.162-6.162-6.162zm0 10.162c-2.209 0-4-1.79-4-4 0-2.209 1.791-4 4-4s4 1.791 4 4c0 2.21-1.791 4-4 4zm6.406-11.845c-.796 0-1.441.645-1.441 1.44s.645 1.44 1.441 1.44c.795 0 1.439-.645 1.439-1.44s-.644-1.44-1.439-1.44z"/></svg>
              </a>
            </motion.div>

          </div>

        </div>

      </div>
    </section>
  );
};

export default Contact;
